def book_of(text):
    t = text or ''
    return next(((k, v) for k, v in BOOK.items() if k in t), None)


def book_link(k):
    u = BOOK_URL.get(k)
    if u: return f'<a class="bkl" href="{E(u)}" rel="nofollow noopener" target="_blank">官网预约 ›</a>'
    h = BOOK_HOW.get(k)
    return f'<span class="bkh">{E(h)}预约</span>' if h else ''


